SkillFunc <- function ( _success )
{
	// 0, 1 or 2, unless the caller forced a variant
	local val = CMND_RANDOM(3);

	if (val == 0)
	{
		SetupNum(1, 0, 0, 1, 2);
		SetupEnable(1, "gol", 0);
	}
	else if (val == 1)
	{
		SetupNum(1, 0, 0, 1, 2);
		SetupMotion(1, "01a");
		SetupEnable(1, "gol", 0);
	}
	else if (val == 2)
	{
		SetupNum(1, 0, 0, 1, 2);
		SetupMotion(1, "01b");
		SetupEnable(1, "gol", 0);
	}
};

// In the event: the last argument (_cmrCut) becomes SP_NUMBER
