// In vsj0001.nut: CMND_RANDOM(2) now returns 0
SkillFunc <- function ( _success )
{
	local val = CMND_RANDOM(2);

	if (val == 0)
	{
		SetupNum(1, 1, 0, 1, 1);
	}
	else
	{
		SetupNum(1, 1, 0, 1, 1);
		SetupMotion(1, "01a");
	}
};
